import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build a shared minimum-cost broadcast tree using directed Steiner DP.

    For small destination sets, each network edge is paid for once and can
    branch at relay clouds to serve several destinations.  For larger sets,
    destinations are greedily attached using paths whose already-selected
    broadcast edges have zero marginal cost.
    """
    import heapq

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(d for d in dsts if d != src))
    h = G.copy()
    h.remove_edges_from(
        list(h.in_edges(src)) + list(nx.selfloop_edges(h)) +
        [(u, v) for u, v, data in h.edges(data=True)
         if data.get("cost") is None]
    )

    def install(edges):
        tree = nx.DiGraph()
        tree.add_edges_from(edges)
        for dst in dsts:
            if dst == src:
                route = []
            else:
                try:
                    nodes = nx.shortest_path(tree, src, dst)
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    nodes = nx.dijkstra_path(h, src, dst, weight="cost")
                route = [[u, v, G[u][v]]
                         for u, v in zip(nodes, nodes[1:])]
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, list(route))

    # dp[mask][v] is the cheapest subtree rooted at v serving terminals in
    # mask.  A reverse shortest-path relaxation permits a subtree to be
    # reached through an arbitrary low-cost relay path.
    if terminals and len(terminals) <= 11 and src in h:
        nodes = list(h)
        pos = {node: i for i, node in enumerate(nodes)}
        if all(dst in pos for dst in terminals):
            count, inf = len(nodes), float("inf")
            size = 1 << len(terminals)
            dp = [[inf] * count for _ in range(size)]
            choice = [[None] * count for _ in range(size)]
            incoming = [[] for _ in nodes]
            for u, v, data in h.edges(data=True):
                incoming[pos[v]].append((pos[u], data["cost"]))

            for mask in range(1, size):
                dist, take = dp[mask], choice[mask]
                if mask & (mask - 1) == 0:
                    i = pos[terminals[mask.bit_length() - 1]]
                    dist[i], take[i] = 0, ("terminal",)
                else:
                    part = (mask - 1) & mask
                    while part:
                        other = mask ^ part
                        if part < other:
                            a, b = dp[part], dp[other]
                            for i in range(count):
                                value = a[i] + b[i]
                                if value < dist[i]:
                                    dist[i] = value
                                    take[i] = ("split", part, other)
                        part = (part - 1) & mask

                queue = [(dist[i], i) for i in range(count) if dist[i] < inf]
                heapq.heapify(queue)
                while queue:
                    value, v = heapq.heappop(queue)
                    if value != dist[v]:
                        continue
                    for u, edge_cost in incoming[v]:
                        candidate = value + edge_cost
                        if candidate < dist[u]:
                            dist[u] = candidate
                            take[u] = ("edge", v)
                            heapq.heappush(queue, (candidate, u))

            root, full = pos[src], size - 1
            if dp[full][root] < inf:
                edges = set()

                def expand(mask, vertex):
                    decision = choice[mask][vertex]
                    if decision[0] == "edge":
                        edges.add((nodes[vertex], nodes[decision[1]]))
                        expand(mask, decision[1])
                    elif decision[0] == "split":
                        expand(decision[1], vertex)
                        expand(decision[2], vertex)

                expand(full, root)
                install(edges)
                return topology

    # Scalable approximation: selected links are reusable broadcast prefixes,
    # so the next attachment pays only for edges not already in the tree.
    selected, reached, pending = set(), {src}, set(terminals)
    while pending:
        def marginal(u, v, data):
            return 0 if (u, v) in selected else data["cost"]

        distances, paths = nx.multi_source_dijkstra(h, reached, weight=marginal)
        candidates = [dst for dst in pending if dst in distances]
        if not candidates:
            break
        dst = min(candidates, key=lambda node: distances[node])
        path = paths[dst]
        selected.update(zip(path, path[1:]))
        reached.update(path)
        pending.difference_update(reached)

    install(selected)
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


